'use strict';
/* Four studios: presentation over the existing data, editor and XN Bridge. */
function uiRoute(route){return ({webnovel:'series',images:'prints',etsy:'prints',pinterest:'prints',ai:'settings',channels:'settings',prompts:'settings',tracking:'overview',metrics:'overview',calendar:'series',publish:'series'})[route]||route}
function uiTotals(month){const rows=db.metrics.filter(m=>String(m.date).slice(0,7)===month);const revenue=rows.reduce((n,m)=>n+Number(m.revenue||0),0),cost=rows.reduce((n,m)=>n+Number(m.cost||0),0);return {rows,revenue,cost,profit:revenue-cost}}
function uiRevenueType(m){const platform=db.channels.find(c=>c.id===m.channelId)?.platform;return platform==='Etsy'?'print':['Webnovel','Web truyện','Webtoon'].includes(platform)||db.series.some(s=>s.channelId===m.channelId)?'story':'other'}
function uiPage(items,page=0,size=3){const pages=Math.max(1,Math.ceil(items.length/size)),index=Math.min(Math.max(0,Number(page)||0),pages-1);return {items:items.slice(index*size,(index+1)*size),page:index,pages,total:items.length}}
function uiProjects(){return [...db.series.map(s=>({id:s.id,title:s.title,type:'story',label:'Xưởng Truyện'})),...(db.printProjects||[]).map(p=>({id:p.id,title:p.title,type:'print',label:'Xưởng In ấn'}))]}
function uiSplitText(text,limit=800){const out=[];for(let start=0;start<text.length;){let end=Math.min(start+limit,text.length);if(end<text.length){const cut=text.slice(start,end).lastIndexOf('\n');if(cut>limit/2)end=start+cut+1}out.push(text.slice(start,end));start=end}return out.length?out:['']}
function uiValidatePrintRecords(value){if(value.printProjects===undefined)return;if(!Array.isArray(value.printProjects))throw Error('Danh sách bộ sản phẩm sai.');const ids=new Set;for(const p of value.printProjects){if(!p||typeof p.id!=='string'||!/^[-\w]+$/.test(p.id)||ids.has(p.id)||typeof p.title!=='string'||!Array.isArray(p.references))throw Error('Dữ liệu bộ sản phẩm / references không hợp lệ.');ids.add(p.id);for(const r of p.references){if(!r||typeof r.id!=='string'||typeof r.title!=='string')throw Error('Mẫu tham khảo không hợp lệ.');if(r.data&&!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(r.data))throw Error('Ảnh tham khảo không hợp lệ.');if(r.link&&!/^https?:\/\//i.test(r.link))throw Error('Link tham khảo không hợp lệ.')}}}
function uiLegacyItems(){const projects=db.printProjects||[],ids=new Set(projects.map(p=>p.id)),linked=new Set(projects.map(p=>p.etsyWorkflowId));return [...(db.assets||[]).filter(a=>!ids.has(a.printProjectId)).map(a=>({id:a.id,title:a.title,type:'asset'})),...(db.workflows||[]).filter(w=>!linked.has(w.id)).map(w=>({id:w.id,title:w.title,type:w.type}))]}
// UI runtime
const uiState={book:'',print:'',storyTab:'produce',printTab:'produce',month:today().slice(0,7),source:'all',pages:{},drafts:{},printDrafts:{},batchDrafts:{}};
const uiLabels={overview:'Tổng quan',series:'Xưởng Truyện',prints:'Xưởng In ấn',settings:'Cài đặt'};
const uiSVG={book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3z M12 6v16',print:'M7 3h10v5H7z M7 16H4V8h16v8h-3 M7 13h10v8H7z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',money:'M5 20V9h3v11 M11 20V4h3v16 M17 20V12h3v8',coins:'M4 7c0-4 16-4 16 0s-16 4-16 0v5c0 4 16 4 16 0V7 M4 12v5c0 4 16 4 16 0v-5',trend:'M3 18l6-6 4 3 8-10 M15 5h6v6',folder:'M3 5h7l2 3h9v13H3z',plug:'M8 2v5 M16 2v5 M5 7h14v5a7 7 0 0 1-14 0z M12 19v3',bell:'M5 17V9a7 7 0 0 1 14 0v8l2 2H3z M10 22h4',image:'M3 3h18v18H3z M3 17l6-7 5 6 3-4 4 5 M16 7h1',info:'M12 8v1 M12 11v7 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',chevron:'M9 5l7 7-7 7',edit:'M4 16L16 4l4 4L8 20H4z'};
function uiIcon(name){return `<svg class="u-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${uiSVG[name]||uiSVG.folder}"/></svg>`}
function uiBadge(text,tone='muted'){return `<span class="u-badge ${tone}">${esc(text)}</span>`}
function uiPager(key,items,size=3){const p=uiPage(items,uiState.pages[key],size);return p.pages>1?`<div class="u-pagination"><button data-ui-page="${key}" data-direction="-1" ${p.page===0?'disabled':''}>‹ Trước</button><span>${p.page+1}/${p.pages}</span><button data-ui-page="${key}" data-direction="1" ${p.page===p.pages-1?'disabled':''}>Sau ›</button></div>`:''}
function uiHint(text){return `<div class="u-hint">${uiIcon('info')}<span>${text}</span></div>`}
function uiHeader(title,subtitle,extra=''){return `<div class="u-page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${extra}</div>`}
function uiChrome(route){$('#sidebar').innerHTML=`<a class="u-brand" href="#overview"><span class="u-logo">X</span><b>Xưởng Nội Dung</b></a><nav id="nav" aria-label="Điều hướng chính">${Object.entries(uiLabels).map(([id,label])=>`<a href="#${id}" ${route===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="u-top-tools"><button class="u-icon-button" data-ui-action="activity" aria-label="Công việc cần xử lý">${uiIcon('bell')}</button><button class="u-avatar" data-ui-action="settings" aria-label="Mở cài đặt">X</button></div>`;document.title=(uiLabels[route]||'Công cụ')+' | Xưởng Nội Dung'}
function uiChart(rows){const year=Number(uiState.month.slice(0,4)),month=Number(uiState.month.slice(5)),days=new Date(year,month,0).getDate(),values=Array.from({length:days},(_,i)=>rows.filter(m=>Number(m.date.slice(8))===i+1).reduce((n,m)=>n+Number(m.revenue||0),0)),max=Math.max(1000,...values),width=830,height=150,pad=110;const coords=values.map((v,i)=>[pad+i*(width-pad-8)/(days-1),height-18-v/max*(height-35)]);return `<svg class="u-chart" viewBox="0 0 ${width} ${height+18}" role="img" aria-label="Doanh thu theo ngày, tháng ${esc(uiState.month)}">${[0,.25,.5,.75,1].map(v=>`<line x1="${pad}" x2="${width}" y1="${height-18-v*(height-35)}" y2="${height-18-v*(height-35)}" stroke="var(--u-line)"/><text x="${pad-8}" y="${height-14-v*(height-35)}" text-anchor="end">${num(Math.round(v*max))}</text>`).join('')}<path d="M${pad},${height-18} L${coords.map(p=>p.join(',')).join(' L')} L${width-8},${height-18}Z" fill="#e0f3e9"/><polyline points="${coords.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#159467" stroke-width="2"/>${coords.filter((_,i)=>i%2===0).map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="2.4" fill="#159467"/>`).join('')}${[1,8,15,22,days].map(n=>`<text x="${pad+(n-1)*(width-pad-8)/(days-1)}" y="${height+9}" text-anchor="${n===days?'end':n===1?'start':'middle'}">${String(n).padStart(2,'0')}/${String(month).padStart(2,'0')}</text>`).join('')}${!rows.length?`<text x="450" y="65" text-anchor="middle">Chưa có số liệu trong tháng</text>`:''}</svg>`}
function uiOverview(){const t=uiTotals(uiState.month),projects=uiProjects(),projectSize=innerHeight<=850?1:3,page=uiPage(projects,uiState.pages.projects,projectSize),byType=[['Xưởng Truyện','story'],['Xưởng In ấn','print'],...(t.rows.some(m=>uiRevenueType(m)==='other')?[['Nguồn khác','other']]:[])].map(([label,type])=>[label,t.rows.filter(m=>uiRevenueType(m)===type).reduce((n,m)=>n+Number(m.revenue||0),0)]);const filtered=uiState.source==='all'?t.rows:t.rows.filter(m=>uiRevenueType(m)===uiState.source);const waiting=db.content.filter(c=>c.status==='review').length;
return `<div class="u-overview">${uiHeader('Tổng quan','Doanh thu, tiến độ dự án và tình trạng vận hành',`<div class="u-actions"><input type="month" id="uMonth" aria-label="Tháng báo cáo" value="${esc(uiState.month)}"><button data-ui-action="report">Xem báo cáo</button></div>`)}<div class="u-kpis">${[['Doanh thu',money(t.revenue),'Theo số liệu đã nhập','money'],['Chi phí',money(t.cost),'Chi phí đã ghi nhận','coins'],['Lợi nhuận',money(t.profit),'Doanh thu trừ chi phí','trend'],['Dự án đang triển khai',projects.length+' dự án','Truyện và bộ sản phẩm','folder']].map(([label,value,note,ico],i)=>`<section class="u-card u-kpi"><span class="u-kpi-icon">${uiIcon(ico)}</span><div><p>${label}</p><strong class="${i===0||i===2?'u-green':''}">${value}</strong><small>${note}</small></div></section>`).join('')}</div><div class="u-overview-middle"><section class="u-card"><div class="u-card-head"><h2>Doanh thu trong tháng</h2><div class="u-segment">${[['all','Tất cả'],['story','Xưởng Truyện'],['print','Xưởng In ấn']].map(([id,label])=>`<button data-ui-source="${id}" class="${uiState.source===id?'selected':''}">${label}</button>`).join('')}</div></div>${uiChart(filtered)}</section><section class="u-card u-revenue-sources"><h2>Doanh thu theo xưởng</h2>${byType.map(([label,n])=>`<div><div class="u-spread"><span>${label}</span><strong>${money(n)}</strong></div><div class="u-bar-row"><span class="u-track"><i style="width:${t.revenue?n/t.revenue*100:0}%"></i></span><small>${t.revenue?(n/t.revenue*100).toFixed(1).replace('.',','):0}%</small></div></div>`).join('')}<small>Theo số liệu đã cập nhật</small></section></div><div class="u-overview-bottom"><section class="u-card"><div class="u-card-head"><h2>Dự án đang triển khai</h2>${uiPager('projects',projects,projectSize)}</div><table class="u-table"><thead><tr><th>Dự án</th><th>Công việc hiện tại</th><th>Tiến độ</th><th>Trạng thái</th><th></th></tr></thead><tbody>${page.items.map(p=>{const s=p.type==='story'?db.series.find(s=>s.id===p.id):null,chapters=s?lfChapters(s):[],approved=chapters.filter(c=>['approved','live'].includes(c.status)).length;return `<tr><td><strong>${esc(p.title)}</strong><small>${uiBadge(p.label,'green')}</small></td><td>${s?(lfApproved(s,'bible')?'Sản xuất chương':'Chuẩn bị cốt truyện'):'Chuẩn bị thiết kế'}</td><td><span class="u-track"><i style="width:${chapters.length?approved/chapters.length*100:0}%"></i></span><small>${s?approved+'/'+chapters.length+' chương':'Đang chuẩn bị'}</small></td><td>${uiBadge(s&&chapters.some(c=>c.status==='review')?'Cần bạn duyệt':'Đang triển khai',s&&chapters.some(c=>c.status==='review')?'amber':'blue')}</td><td><button class="u-text" data-ui-open="${p.id}" data-project-type="${p.type}">Mở dự án ›</button></td></tr>`}).join('')||'<tr><td colspan="5" class="u-empty">Chưa có dự án. Tạo bộ truyện hoặc bộ sản phẩm để bắt đầu.</td></tr>'}</tbody></table></section><section class="u-card"><h2>Tình trạng phần mềm</h2>${uiHealth()}<div class="u-spread u-card-foot"><small>Quản lý kết nối và phần mềm trong Cài đặt</small><button class="u-text" data-ui-action="settings">Mở cài đặt ›</button></div></section></div><div class="u-alert u-spread"><span>● &nbsp; Cần xử lý: ${waiting?waiting+' nội dung đang chờ duyệt':'Chưa có công việc chờ duyệt'}</span><button class="u-text" data-ui-action="activity">Xem công việc ›</button></div></div>`}
function uiHealth(){const state=bridgeConnectionState();return `<div class="u-health"><div><span>Web Xưởng</span><span class="u-dot green">Hoạt động</span></div><div><span>ChatGPT Bridge</span><span id="uBridgeHealth" class="u-dot ${state.tone==='connected'?'green':'red'}">${esc(state.label.replace(' — không nhận được Bridge',''))}</span></div><div><span>Tự động hóa in ấn</span><span class="u-dot muted">Chưa triển khai</span></div><div><span>Lưu dữ liệu</span><span class="u-dot ${loadError?'red':'green'}">${loadError?'Cần khôi phục':'Đã lưu trên trình duyệt'}</span></div></div>`}
function uiLibrary(type){const list=type==='story'?db.series:(db.printProjects||[]),selected=type==='story'?uiState.book:uiState.print,key=type==='story'?'books':'prints',p=uiPage(list,uiState.pages[key],4);return `<aside class="u-library"><h2>${type==='story'?'Bộ truyện của tôi':'Bộ sản phẩm của tôi'}</h2><button class="${type==='story'?'primary':''} u-wide" data-ui-action="${type==='story'?'new-book':'new-print'}">＋ Tạo ${type==='story'?'truyện mới':'bộ sản phẩm'}</button><div class="u-library-items">${p.items.map(item=>`<button class="u-library-item ${selected===item.id?'active':''}" data-ui-select="${item.id}" data-project-type="${type}"><span class="u-dot ${type==='story'&&lfApproved(item,'bible')?'green':'amber'}"></span><span><strong>${esc(item.title)}</strong><small>${type==='story'?`${lfChapters(item).length} chương · ${lfApproved(item,'bible')?'Đã duyệt cốt truyện':'Đang chuẩn bị'}`:(db.assets||[]).filter(a=>a.printProjectId===item.id).length+' thiết kế'}</small></span></button>`).join('')||'<p class="u-empty">Chưa có dự án.</p>'}</div>${uiPager(key,list,4)}${type==='print'&&uiLegacyItems().length?`<button data-ui-action="legacy-assets">Ảnh / sản phẩm hiện có (${uiLegacyItems().length})</button>`:''}${uiHint('Chọn '+(type==='story'?'truyện':'bộ sản phẩm')+' để sản xuất tiếp')}</aside>`}
/* Xưởng Truyện: one renderer for the empty, new-story and selected-story states. */
const uiStoryDirections=[['continue','Tiếp tục câu chuyện','Tiếp tục mạch truyện theo dàn ý đã duyệt.'],['arc','Phát triển Arc hiện tại','Đào sâu Arc đang chạy, chưa khép các nút thắt chính.'],['newarc','Mở Arc mới','Khép dần Arc hiện tại và mở một Arc mới.'],['open','Chuẩn bị kết mở','Giải quyết xung đột trung tâm nhưng giữ khả năng tiếp nối.'],['closed','Chuẩn bị kết đóng','Khép trọn vẹn các nút thắt bằng sự kiện thực sự.']];
const uiStoryDraftKey='xuong-story-new-draft';
function uiStoryNewDraft(){if(!uiState.newDraft){try{uiState.newDraft=JSON.parse(localStorage.getItem(uiStoryDraftKey)||'{}')||{}}catch{uiState.newDraft={}}}return uiState.newDraft}
function uiStoryKeepDraft(){try{localStorage.setItem(uiStoryDraftKey,JSON.stringify(uiState.newDraft||{}))}catch{}}
function uiStoryStatus(s){if(lfApproved(s,'bible'))return{tone:'green',label:'Cốt truyện đã duyệt'};const a=lfPipeline(s).artifacts||{};if(Object.keys(a).length||(db.aiJobs||[]).some(j=>j.seriesId===s.id&&j.storyTask))return{tone:'amber',label:'Đang xây dựng cốt truyện'};return{tone:'muted',label:'Chưa triển khai'}}
function uiStoryIcon(name){return `<svg class="st-ico" viewBox="0 0 24 24" aria-hidden="true"><path d="${({plus:'M12 5v14 M5 12h14',check:'M5 12.5l4.5 4.5L19 7.5',edit:'M4 20h4L19 9l-4-4L4 16z M13.5 6.5l4 4',book:'M3 5.5C5.5 4 8.5 4 12 6c3.5-2 6.5-2 9-.5V19c-2.5-1.5-5.5-1.5-9 .5-3.5-2-6.5-2-9-.5z M12 6v13.5',bulb:'M9 18h6 M10 21h4 M12 3a6 6 0 0 0-3.5 10.9c.6.5 1 1.2 1 2.1h5c0-.9.4-1.6 1-2.1A6 6 0 0 0 12 3z',info:'M12 11v6 M12 7.5v.5 M12 2.5a9.5 9.5 0 1 0 0 19 9.5 9.5 0 0 0 0-19',alert:'M12 7v6 M12 16.5v.5'})[name]}"/></svg>`}
function uiStoryLibrary(){const list=db.series,p=uiPage(list,uiState.pages.books,6);const draft=uiState.creating||!list.length?`<button class="st-item ${uiState.creating||!list.length?'active':''}" data-ui-action="new-book"><i class="st-dot muted"></i><span><strong>${esc(uiStoryNewDraft().topic?.trim().slice(0,40)||'Bộ truyện mới')}</strong><small>Đang nhập ý tưởng</small></span></button>`:'';return `<div class="st-library"><h2>Bộ truyện của tôi</h2><button class="primary st-new" data-ui-action="new-book">${uiStoryIcon('plus')}Tạo truyện mới</button><div class="st-items">${draft}${p.items.map(s=>{const st=uiStoryStatus(s),n=lfChapters(s).length;return `<button class="st-item ${!uiState.creating&&uiState.book===s.id?'active':''}" data-ui-select="${s.id}" data-project-type="story"><i class="st-dot ${st.tone}"></i><span><strong>${esc(s.title)}</strong><small>${st.label}${n||st.tone==='green'?' • '+n+' chương':''}</small></span></button>`}).join('')}</div>${uiPager('books',list,6)}<div class="st-library-foot">${uiStoryIcon('book')}Chọn truyện để sản xuất tiếp</div></div>`}
function uiStorySteps(step){return `<div class="st-steps">${['Ý tưởng & nguồn','Cốt truyện & nhân vật','Sản xuất chương'].map((label,i)=>`${i?'<i></i>':''}<span class="${i+1===step?'active':i+1<step?'done':''}"><b>${i+1<step?uiStoryIcon('check'):i+1}</b>${i+1}. ${label}</span>`).join('')}</div>`}
function uiStorySource(src,isNew){const f=isNew?'data-ui-new-field':'data-ui-story-field';return `<section class="st-section st-source"><h3>Ý tưởng & nguồn tham khảo</h3><div class="st-source-grid"><div class="st-col"><label for="uStoryIdea">Ý tưởng chính của truyện</label><textarea id="uStoryIdea" ${f}="topic" placeholder="Nhập chủ đề hoặc ý tưởng chính của bộ truyện…">${esc(src.topic||'')}</textarea><div class="st-row"><button class="st-outline" data-ui-action="${isNew?'create-from-idea':'build-story'}">Xây dựng / cập nhật cốt truyện</button>${isNew?(uiState.creating&&db.series.length?'<button class="st-link" data-ui-action="cancel-new">Hủy</button>':''):'<button class="st-link" data-ui-action="reference-script">Dán script / transcript</button>'}</div></div><div class="st-col"><label for="uStoryLink">Link truyện / YouTube tham khảo (tùy chọn)</label><input id="uStoryLink" ${f}="referenceLink" placeholder="Dán link tham khảo hoặc bổ sung transcript…" value="${esc(src.referenceLink||'')}"><label for="uStoryStyle">Câu lệnh văn phong cá nhân (tùy chọn)</label><textarea id="uStoryStyle" class="st-style" ${f}="options" placeholder="Để trống để ChatGPT tự đề xuất văn phong phù hợp">${esc(src.options||'')}</textarea></div></div></section>`}
function uiStoryDetails(s){const p=s?lfPipeline(s):null,bible=p?.artifacts.bible?.value,chars=s?(p.artifacts.characters?.value?.characters||lfData(s).characters||[]):[],twists=String(bible?.mainThreads||'').split('\n').map(x=>x.replace(/^[-•*\d.)\s]+/,'').trim()).filter(Boolean),dis=s?'':'disabled';return `<section class="st-section st-details ${s?'':'st-disabled'}"><div class="st-head"><h3>Cốt truyện & nhân vật</h3>${s?`<button class="st-link" data-ui-action="glossary">Thuật ngữ & văn phong (${lfData(s).glossary.length})</button>`:''}${bible?.reviewVi?'<button class="st-link" data-ui-action="review-vi-bible">Bản tiếng Việt</button>':''}<button class="st-link" data-ui-action="edit-bible" ${dis}>${uiStoryIcon('edit')}Chỉnh sửa</button></div><div class="st-detail-grid"><div class="st-col"><b>Cốt truyện tổng quan</b><div class="st-synopsis ${bible?.premise||s?.synopsis?'':'muted'}">${esc(bible?.premise||s?.synopsis||(s?'Chưa xây dựng cốt truyện. Nhập ý tưởng rồi bấm Xây dựng / cập nhật cốt truyện.':'Cốt truyện sẽ xuất hiện tại đây sau khi xây dựng.'))}</div><b>Twist & nút thắt</b><div class="st-twists">${(twists.length?twists.slice(0,3):[s?'Chưa có twist. ChatGPT sẽ đề xuất để bạn duyệt.':'Các nút thắt sẽ được đề xuất để bạn duyệt.']).map(x=>`<div class="st-twist ${twists.length?'':'muted'}"><i></i><span>${esc(x)}</span></div>`).join('')}</div></div><div class="st-col"><b>Nhân vật</b><div class="st-cast">${chars.slice(0,3).map((c,i)=>`<div class="st-char"><span class="st-initial c${i%3}">${esc((c.name||c.title||'?').trim().slice(0,1).toUpperCase())}</span><span class="st-char-name"><strong>${esc(c.name||c.title||'Nhân vật')}</strong><small>${esc(c.role||'Nhân vật')}</small></span><span class="st-char-desc">${esc(String(c.personality||c.goal||c.motivation||c.arc||c.body||'').slice(0,110))}</span><button class="st-icon-btn" data-ui-character="${esc(c.id||'character_'+i)}" aria-label="Chỉnh sửa ${esc(c.name||'nhân vật')}">${uiStoryIcon('edit')}</button></div>`).join('')||`<p class="st-empty">${s?'Nhân vật sẽ hiện sau khi ChatGPT xây dựng và bạn duyệt.':'Nhân vật sẽ xuất hiện tại đây sau khi xây dựng cốt truyện.'}</p>`}${chars.length>3?`<button class="st-link st-more" data-ui-action="story-characters">Xem tất cả ${chars.length} nhân vật ›</button>`:''}</div></div></div><div class="st-foot"><div class="st-warn"><span>${uiStoryIcon('alert')}</span>Có thể bổ sung tình tiết giữa chừng; chương đã duyệt được giữ nguyên.</div><button class="st-outline" data-ui-action="story-advanced" ${dis}>Điều chỉnh hướng truyện</button></div></section>`}
function uiStorySuggestion(s,count){const n=lfNextChapter(s),end=n+count-1,arc=lfData(s).plans.filter(x=>['arc','volume'].includes(x.kind)&&Number(x.startChapter)<=end&&Number(x.endChapter)>=n).sort((a,b)=>(a.kind==='arc')-(b.kind==='arc')).at(-1);return arc?`Chương ${n}–${end} phát triển ${arc.title}${arc.body?': '+String(arc.body).slice(0,90):''}.`:`Chương ${n}–${end} phát triển nút thắt chưa giải quyết; giữ nhất quán với các chương đã duyệt.`}
function uiStoryBatch(s){const batch={...s?.uiBatch,...(s?uiState.batchDrafts[s.id]:{})},count=Math.min(30,Math.max(1,Number(batch.count)||10)),dir=uiStoryDirections.find(d=>d[0]===batch.ending)||uiStoryDirections[0],total=s?lfChapters(s).length:0,n=s?lfNextChapter(s):1,stage=s?uiCurrentStage(s):null,ready=s&&lfApproved(s,'outline'),dis=s?'':'disabled',tip=s?(ready?uiStorySuggestion(s,count):`Duyệt ${stage[1]} để mở khóa sản xuất chương.`):'Hoàn thiện và duyệt cốt truyện trước khi sản xuất chương.';return `<section class="st-section st-batch ${s?'':'st-disabled'}"><h3>Sản xuất đợt tiếp theo</h3><p class="st-sub">${s?`Đã có ${total} chương • Đợt mới bắt đầu từ Chương ${n}`:'Chưa có chương • Đợt đầu bắt đầu từ Chương 1'}</p><div class="st-batch-row"><label class="st-inline"><span>Số chương đợt này</span><input id="uChapterCount" type="number" min="1" max="30" value="${count}" ${dis}></label><label class="st-inline st-direction"><span>Hướng phát triển</span><span class="st-select"><select id="uEnding" ${dis}>${uiStoryDirections.map(([v,l])=>`<option value="${v}" ${v===dir[0]?'selected':''}>${l}</option>`).join('')}</select><small id="uEndingHint">${dir[2]}</small></span></label><button class="primary st-produce" id="uBatchButton" data-ui-action="batch" ${dis}>Sản xuất ${count} chương</button></div><label class="st-inline st-extra"><span>Yêu cầu bổ sung cho đợt này (tùy chọn)</span><input id="uBatchOptions" value="${esc(batch.options||'')}" placeholder="Ví dụ: đẩy mạnh xung đột giữa hai nhân vật chính…" ${dis}></label><div class="st-tip">${uiStoryIcon('bulb')}<span><b>Gợi ý:</b> <span id="uBatchTip">${esc(tip)}</span></span>${ready?'<button class="st-link" data-ui-action="use-suggestion">Dùng gợi ý</button>':''}</div><p class="st-note">${uiStoryIcon('info')}Nội dung được tạo ở bản nháp và chờ bạn duyệt trước khi đăng.</p></section>`}
function uiStoryBook(s){const st=s?uiStoryStatus(s):{tone:'muted',label:'Chưa triển khai'},stage=s?uiCurrentStage(s):['concept'],step=!s?1:stage[0]==='ready'?3:['dna','concept'].includes(stage[0])?1:2,src=s?{...lfPipeline(s).source,...uiState.drafts[s.id]}:uiStoryNewDraft(),jobs=s?(db.aiJobs||[]).filter(j=>j.seriesId===s.id&&j.storyTask):[],j=jobs.filter(j=>['queued','waiting_send','running','ready','error'].includes(j.status)).at(-1);return `<section class="st-panel"><div class="st-title"><h2>${esc(s?s.title:'Bộ truyện mới')}</h2><span class="st-badge ${st.tone}"><i></i>${st.label}</span><label class="st-lang">Ngôn ngữ truyện<select id="uStoryLang">${[...new Set(['English','Tiếng Việt',s?lfStoryLang(s):(uiStoryNewDraft().storyLanguage||'English')])].map(l=>`<option ${l===(s?lfStoryLang(s):(uiStoryNewDraft().storyLanguage||'English'))?'selected':''}>${esc(l)}</option>`).join('')}</select></label><span class="st-spacer"></span>${s?`<button class="st-link" data-ui-action="chapters">Danh sách chương (${lfChapters(s).length}) ›</button>`:''}</div>${uiStorySteps(step)}${s?uiStoryJob(s,stage,j):''}${uiStorySource(src,!s)}${uiStoryDetails(s)}${uiStoryBatch(s)}</section>`}
function uiStory(){const books=db.series;if(uiState.creating&&!books.length)uiState.creating=false;if(!uiState.creating&&!books.some(s=>s.id===uiState.book)){let saved='';try{saved=localStorage.getItem('xuong-story-selected')||''}catch{}uiState.book=books.some(s=>s.id===saved)?saved:books[0]?.id||''}const s=uiState.creating?null:books.find(s=>s.id===uiState.book);try{if(s)localStorage.setItem('xuong-story-selected',s.id)}catch{}return `<div class="st-workspace">${uiStoryLibrary()}<div class="st-studio"><div class="st-heading"><h1>Xưởng Truyện</h1><p>Từ ý tưởng đến bộ truyện hoàn chỉnh, sản xuất từng đợt chương.</p></div><div class="st-tabs" role="tablist"><button role="tab" aria-selected="${uiState.storyTab!=='publish'}" data-ui-storytab="produce" class="${uiState.storyTab!=='publish'?'active':''}">Sản xuất truyện</button><button role="tab" aria-selected="${uiState.storyTab==='publish'}" data-ui-storytab="publish" class="${uiState.storyTab==='publish'?'active':''}">Kết nối đăng truyện</button></div>${uiState.storyTab==='publish'?uiPublishing('story',s):uiStoryBook(s)}</div></div>`}
function uiCheckHTML(s,c,body){const r=lfChapterCheck(s,body),sum=lfCheckSummary(r),icon={ok:'✓',warn:'!',error:'✕'};let ai='';if(c?.aiReview){const v=c.aiReview.value,fresh=lfAIReviewFresh(c)&&String(body)===String(c.body||'');ai='<div class="u-check-ai"><p><b>ChatGPT: '+(v.verdict==='ok'?'Đạt':'Cần sửa')+'</b>'+(fresh?'':' <span class="u-check-stale">(cũ — chương đã sửa sau lần kiểm tra)</span>')+'</p><p>Mở chương '+v.hook.score+'/5: '+esc(v.hook.note)+'</p><p>Kết chương '+v.ending.score+'/5: '+esc(v.ending.note)+'</p><p>Kế hoạch: '+esc(v.planCoverage)+'</p>'+(v.contradictions.length?'<p><b>Mâu thuẫn</b></p><ul>'+v.contradictions.map(x=>'<li>'+esc(x.issue)+(x.evidence?' — <i>“'+esc(x.evidence)+'”</i>':'')+'</li>').join('')+'</ul>':'')+(v.styleIssues.length?'<p><b>Văn phong</b></p><ul>'+v.styleIssues.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'')+'<p class="u-pre">'+esc(v.summaryVi)+'</p></div>'}return '<p class="u-check-head"><span class="u-check-badge '+sum.tone+'">'+esc(sum.label)+'</span>'+(c?'<button type="button" data-ui-chapter-check="'+c.id+'">ChatGPT kiểm tra (bản đã lưu)</button>':'')+'</p><ul class="u-check-list">'+r.items.map(i=>'<li class="'+i.level+'"><span>'+icon[i.level]+'</span><b>'+esc(i.title)+'</b>'+(i.detail?' — '+esc(i.detail):'')+'</li>').join('')+'</ul>'+ai}
function uiCheckPanel(type,id,defaults){document.querySelector('#uCheckPanel')?.remove();if(type!=='content'||!$('#editor').open)return;const c=id?db.content.find(x=>x.id===id):null,sid=c?.seriesId||defaults?.seriesId,task=c?.productionTask||defaults?.productionTask,s=db.series.find(x=>x.id===sid);if(!s||task!=='chapter'||s.channelId!==findWebnovelChannel()?.id)return;const el=document.createElement('details');el.id='uCheckPanel';el.className='u-review-vi u-check';el.open=true;el.innerHTML='<summary>Kiểm tra trước khi duyệt</summary><div class="u-check-body"></div>';$('#fields').before(el);const field=$('#fields [name=body]'),paint=()=>{el.querySelector('.u-check-body').innerHTML=uiCheckHTML(s,c,field?field.value:c?.body||'')};paint();let t;field?.addEventListener('input',()=>{clearTimeout(t);t=setTimeout(paint,400)})}
function uiReviewPanel(type,id){document.querySelector('#uReviewViPanel')?.remove();const c=type==='content'&&id?db.content.find(c=>c.id===id):null;if(!c?.reviewVi||!$('#editor').open)return;const el=document.createElement('details');el.id='uReviewViPanel';el.className='u-review-vi';el.innerHTML='<summary></summary><div></div>';el.firstChild.textContent=lfReviewFresh(c)?'Bản tiếng Việt để duyệt':'Bản tiếng Việt (cũ — chương đã sửa sau khi dịch)';el.lastChild.textContent=c.reviewVi;$('#fields').before(el)}
function uiGlossary(s){const sd=lfData(s),g=sd.glossary;uiReadDocument(`<div class="u-spread"><h3>Văn phong (${esc(lfStoryLang(s))})</h3><button data-ui-action="glossary-style">${sd.styleGuide?'Sửa văn phong':'Tạo văn phong'}</button></div><p class="u-pre">${esc(sd.styleGuide||'Chưa có style guide. Bấm Tạo văn phong hoặc để ChatGPT đề xuất.')}</p><div class="u-spread"><h3>Thuật ngữ (${g.length})</h3><div class="u-actions"><button data-ui-action="glossary-add">＋ Thêm</button><button data-ui-action="glossary-cast">Lấy tên nhân vật</button><button data-ui-action="glossary-ai">ChatGPT đề xuất</button></div></div>${g.map(x=>`<article class="u-chapter-row"><div><strong>${esc(x.term)}</strong><small>${esc([x.kind,x.note,x.vi?'VI: '+x.vi:''].filter(Boolean).join(' · '))}</small></div><button data-ui-glossary-edit="${x.id}">Sửa</button><button data-ui-glossary-del="${x.id}">Xóa</button></article>`).join('')||'<p>Chưa có thuật ngữ.</p>'}<p>Văn phong và thuật ngữ được gửi kèm mọi yêu cầu ChatGPT của bộ truyện này, kể cả bản dịch duyệt.</p>`,'Thuật ngữ & văn phong')}
async function uiGlossaryEdit(s,id){const sd=lfData(s),old=sd.glossary.find(x=>x.id===id)||{};const d=await choose(old.id?'Sửa thuật ngữ':'Thêm thuật ngữ',input('term','Thuật ngữ / tên riêng ('+lfStoryLang(s)+')',old.term||'','text','required')+select('kind','Loại',lfGlossaryKinds(),old.kind||'Nhân vật')+input('note','Ghi chú cách dùng',old.note||'')+input('vi','Cách gọi khi dịch tiếng Việt (tùy chọn)',old.vi||''));if(!d)return;const term=String(d.term||'').trim();if(!term)throw Error('Nhập thuật ngữ.');if(sd.glossary.some(x=>x.id!==old.id&&String(x.term).trim().toLowerCase()===term.toLowerCase()))throw Error('Thuật ngữ đã có.');uiPersist(()=>{const v={term,kind:lfGlossaryKinds().includes(d.kind)?d.kind:'Thuật ngữ khác',note:String(d.note||'').trim(),vi:String(d.vi||'').trim()};const cur=sd.glossary.find(x=>x.id===old.id);if(cur)Object.assign(cur,v);else sd.glossary.push({id:uid(),...v})})}
function uiStyleTemplate(s){return /^english/i.test(lfStoryLang(s))?'POV: third person limited, following the protagonist\nTense: past tense\nSpelling: American English\nTone: \nPacing: short paragraphs, quick scene transitions\nDialogue: natural, contractions allowed; no info-dumps in dialogue\nChapters: hook in the first lines, end on a cliffhanger or open question\nAvoid: "tapestry", "testament to", "a symphony of", "delve", "in the realm of", "shivers down her spine"; purple prose; repeated sentence openings':'Ngôi kể: \nThì: \nGiọng văn: \nThoại: \nMở / kết chương: \nTránh: '}
async function uiStyleEdit(s){const sd=lfData(s),d=await choose('Văn phong ('+lfStoryLang(s)+')',input('styleGuide','Style guide — gửi kèm mọi yêu cầu ChatGPT',sd.styleGuide||uiStyleTemplate(s),'textarea','rows="12"'));if(!d)return;const v=String(d.styleGuide||'').trim();uiPersist(()=>{if(sd.styleGuide&&sd.styleGuide!==v)sd.styleGuidePrev=sd.styleGuide;sd.styleGuide=v})}
function uiWorkingTitle(topic){let t=topic.replace(/\s+/g,' ').trim().split(/[.!?\n]/)[0];const comma=t.indexOf(',');if(t.length>60&&comma>=12)t=t.slice(0,comma);return t.length>60?t.slice(0,57).replace(/\s+\S*$/,'')+'…':t}
async function uiCreateFromIdea(){const d=uiStoryNewDraft(),topic=String(d.topic||'').trim();if(!topic){$('#uStoryIdea')?.focus();throw Error('Nhập ý tưởng chính của truyện trước.')}let c=findWebnovelChannel();if(!c){db.setup??={};prepareWebnovel();c=findWebnovelChannel()}if(!c)throw Error('Chưa có kênh Webnovel. Thêm kênh trong Kết nối đăng truyện.');const s={id:uid(),title:uiWorkingTitle(topic),channelId:c.id,storyLanguage:String(d.storyLanguage||'English'),outline:'',characters:'',chapterLength:1500,exclusivity:'Không độc quyền'};lfSetSource(s,{mode:'topic',topic,referenceLink:String(d.referenceLink||'').trim(),genre:'',chapters:20,options:String(d.options||'')});uiPersist(()=>db.series.push(s));uiState.book=s.id;uiState.creating=false;uiState.newDraft={};uiStoryKeepDraft();uiState.pages.books=Math.floor((db.series.length-1)/6);uiRender();try{await uiBuildStory(s)}catch(e){toast('Đã tạo bộ truyện. '+e.message)}}
function uiCurrentStage(s){const p=lfPipeline(s);if(p.source.mode==='reference'&&!lfApproved(s,'dna'))return ['dna','Content DNA','ANALYZE_REFERENCE_SCRIPT'];for(const [stage,label,kind]of [['concept','Concept','GENERATE_CONCEPT'],['bible','Cốt truyện tổng quan','GENERATE_STORY_BIBLE'],['characters','Nhân vật','GENERATE_CHARACTERS'],['outline','Dàn ý chương','GENERATE_OUTLINE']])if(!lfApproved(s,stage))return [stage,label,kind];return ['ready','Sẵn sàng viết chương','']}
function uiStoryJob(s,stage,j){if(j)return `<div class="u-job u-spread"><div><strong>${esc(lfJobKinds[j.storyTask]||'Công việc AI')}</strong><small>${esc(jobState(j))}${j.error?' · '+esc(j.error):''}</small></div><div class="u-actions">${j.status==='ready'?`<button class="primary" data-ui-apply="${j.id}">Xem và áp dụng kết quả</button>`:''}${j.resultText?`<button data-ui-result="${j.id}">Xem kết quả</button>`:''}${['ready','error','queued','waiting_send','running'].includes(j.status)?`<button data-ui-discard="${j.id}">Dừng / giữ kết quả</button>`:''}</div></div>`;const a=lfPipeline(s).artifacts[stage[0]];return stage[0]==='ready'||!a?'':`<div class="u-job u-spread"><span>Bước tiếp theo: <strong>${stage[1]}</strong> · ${a?'Cần bạn duyệt':'Chưa triển khai'}</span><div class="u-actions">${a?'<button data-ui-action="review-stage">Xem / chỉnh kết quả</button><button class="primary" data-ui-action="approve-stage">Duyệt và tiếp tục</button>':'<button class="primary" data-ui-action="build-story">Tạo bằng ChatGPT</button>'}</div></div>`}
/* Xưởng In ấn: one renderer for the empty, new-set and selected-set states. */
const uiPrintDraftKey='xuong-print-new-draft',uiPrintProducts=['Áo thun','Poster','Sản phẩm số','Khác'],uiPrintOutputs=['PNG nền trong','PNG','JPEG'],uiPrintSources=['Pinterest','Google','Etsy'];
function uiPrintNewDraft(){if(!uiState.newPrint){try{uiState.newPrint=JSON.parse(localStorage.getItem(uiPrintDraftKey)||'{}')||{}}catch{uiState.newPrint={}}}return uiState.newPrint}
function uiPrintKeepDraft(){try{localStorage.setItem(uiPrintDraftKey,JSON.stringify(uiState.newPrint||{}))}catch{}}
function uiPrintIcon(name){return `<svg class="pr-ico" viewBox="0 0 24 24" aria-hidden="true"><path d="${({shirt:'M8.5 3.5L3 6.5l2 4 2.5-1V20h9V9.5l2.5 1 2-4-5.5-3c-.6 1.6-2 2.5-3.5 2.5s-2.9-.9-3.5-2.5z',image:'M4 4h16v16H4z M4 16l5-5 4 4 3-3 4 4 M15 8.5h.01',doc:'M6 3h9l4 4v14H6z M14 3v5h5 M9 13h7 M9 17h5',box:'M3 7l9-4 9 4v10l-9 4-9-4z M3 7l9 4 9-4 M12 11v10',tag:'M3 12V4h8l10 10-8 8z M7.5 7.5h.01',price:'M20.5 12.5l-8 8-9-9V3.5h8z M7.5 7.5h.01',clock:'M12 7v5l3 2 M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18',chevron:'M9 6l6 6-6 6',arrow:'M5 12h14 M13 6l6 6-6 6',check:'M5 12.5l4.5 4.5L19 7.5',plus:'M12 5v14 M5 12h14',info:'M12 11v6 M12 7.5v.5 M12 2.5a9.5 9.5 0 1 0 0 19 9.5 9.5 0 0 0 0-19',link:'M10 14a4 4 0 0 0 6 0l3-3a4 4 0 0 0-6-6l-1 1 M14 10a4 4 0 0 0-6 0l-3 3a4 4 0 0 0 6 6l1-1'})[name]}"/></svg>`}
function uiPrintTypeIcon(t){return t==='Áo thun'?'shirt':t==='Poster'?'image':t==='Sản phẩm số'?'doc':'box'}
function uiPrintStats(p){const assets=(db.assets||[]).filter(a=>a.printProjectId===p.id),created=assets.filter(a=>a.data),approved=created.filter(a=>a.approval==='approved'),count=Number(p.count)||12;return{assets,created,approved,count}}
function uiPrintStatus(p){const s=uiPrintStats(p);if(!s.assets.length)return(p.references||[]).length||p.keyword?'Đang chuẩn bị':'Chưa triển khai';if(s.created.length<s.count)return `${s.created.length}/${s.count} thiết kế · Đang sản xuất`;if(s.approved.length<s.created.length)return 'Chờ duyệt thiết kế';return `${s.count} thiết kế · Đã duyệt`}
function uiPrintLibrary(){const list=db.printProjects||[],pg=uiPage(list,uiState.pages.prints,6),creating=uiState.creatingPrint||!list.length,legacy=uiLegacyItems().length;return `<div class="pr-library"><h2>Bộ sản phẩm của tôi</h2><button class="pr-new" data-ui-action="new-print">${uiPrintIcon('plus')}Tạo bộ sản phẩm</button><div class="pr-items">${creating?`<button class="pr-item active" data-ui-action="new-print"><span class="pr-item-icon">${uiPrintIcon(uiPrintTypeIcon(uiPrintNewDraft().productType||'Áo thun'))}</span><span><strong>${esc(String(uiPrintNewDraft().keyword||'').trim().slice(0,40)||'Bộ sản phẩm mới')}</strong><small>Đang nhập định hướng</small></span></button>`:''}${pg.items.map(p=>`<button class="pr-item ${!creating&&uiState.print===p.id?'active':''}" data-ui-select="${p.id}" data-project-type="print"><span class="pr-item-icon">${uiPrintIcon(uiPrintTypeIcon(p.productType))}</span><span><strong>${esc(p.title)}</strong><small>${esc(uiPrintStatus(p))}</small></span></button>`).join('')}</div>${uiPager('prints',list,6)}${legacy?`<button class="pr-link pr-legacy" data-ui-action="legacy-assets">Ảnh / sản phẩm hiện có (${legacy})</button>`:''}<div class="pr-library-foot">${uiPrintIcon('info')}Chọn bộ sản phẩm để sản xuất tiếp</div></div>`}
function uiPrintSteps(step){return `<div class="pr-steps">${['Tìm ý tưởng','Tạo thiết kế','Chuẩn bị đăng Etsy'].map((label,i)=>`${i?'<i></i>':''}<span class="${i+1===step?'active':i+1<step?'done':''}"><b>${i+1<step?uiPrintIcon('check'):i+1}</b>${i+1}. ${label}</span>`).join('')}</div>`}
function uiPrintSource(p,isNew){const f=isNew?'data-ui-newprint-field':'data-ui-print-field',sf=isNew?'data-ui-newprint-source':'data-ui-print-source',sources=p.sources||uiPrintSources,count=Number(p.count)||12,counts=[...new Set([4,6,8,10,12,16,20,24,30,40,50,count])].sort((a,b)=>a-b);return `<section class="pr-section pr-source"><h3>Nguồn tham khảo & định hướng</h3><div class="pr-source-grid"><div class="pr-col"><label for="uPrintKeyword">Chủ đề / từ khóa</label><input id="uPrintKeyword" ${f}="keyword" value="${esc(p.keyword||'')}" placeholder="Ví dụ: Áo chữ tối giản cho người yêu đọc sách"><p class="pr-label">Nguồn tham khảo</p><div class="pr-checks">${uiPrintSources.map(n=>`<label><input type="checkbox" ${sf}="${n}" ${sources.includes(n)?'checked':''}>${n}</label>`).join('')}</div><div class="pr-row"><button class="pr-outline" data-ui-action="find-references">Tìm sản phẩm tham khảo</button><span class="pr-pill">Chờ tích hợp</span></div><small class="pr-hint">Có thể dán link hoặc thêm ảnh tham khảo thủ công</small></div><div class="pr-col"><label for="uPrintStyle">Phong cách thiết kế</label><textarea id="uPrintStyle" ${f}="style" placeholder="Màu sắc, kiểu chữ, bố cục, phong cách…">${esc(p.style||'')}</textarea><div class="pr-three"><label>Sản phẩm<select ${f}="productType">${uiPrintProducts.map(v=>`<option ${v===(p.productType||'Áo thun')?'selected':''}>${v}</option>`).join('')}</select></label><label>Số thiết kế<select ${f}="count">${counts.map(v=>`<option value="${v}" ${v===count?'selected':''}>${v}</option>`).join('')}</select></label><label>Đầu ra<select ${f}="output">${uiPrintOutputs.map(v=>`<option ${v===(p.output||'PNG nền trong')?'selected':''}>${v}</option>`).join('')}</select></label></div></div></div>${isNew?`<div class="pr-create"><button class="primary pr-primary" data-ui-action="create-print">Tạo bộ sản phẩm từ định hướng này</button>${uiState.creatingPrint&&(db.printProjects||[]).length?'<button class="pr-link" data-ui-action="cancel-new-print">Hủy</button>':''}<small>Nhập chủ đề, chọn sản phẩm rồi tạo để thêm mẫu tham khảo và thiết kế.</small></div>`:''}</section>`}
function uiPrintRefSource(r){const s=String(r.source||'');return /pinterest/i.test(s)?'Pinterest':/google/i.test(s)?'Google':/etsy/i.test(s)?'Etsy':s||'Tham khảo'}
function uiPrintRefs(p){const refs=p?(p.references||[]):[],pg=uiPage(refs,uiState.pages.references,4),dis=p?'':'disabled';const cards=pg.items.map(r=>`<figure class="pr-ref ${r.selected?'selected':''}"><button class="pr-ref-thumb" data-ui-reference="${r.id}" aria-label="Xem ${esc(r.title)}">${r.data?`<img src="${esc(r.data)}" alt="${esc(r.title)}">`:`<span class="pr-placeholder">${uiPrintIcon('link')}<span>${esc(r.title||'Link tham khảo')}</span></span>`}</button><button class="pr-ref-check" data-ui-ref-select="${r.id}" aria-pressed="${!!r.selected}" aria-label="${r.selected?'Bỏ chọn':'Chọn'} mẫu ${esc(r.title)}">${r.selected?uiPrintIcon('check'):''}</button><figcaption>${esc(r.link||r.data?uiPrintRefSource(r)+' · Tham khảo':'Ý tưởng mới')}</figcaption></figure>`).join('');const fill=Array.from({length:Math.max(0,4-pg.items.length)},(_,i)=>`<figure class="pr-ref empty"><button class="pr-ref-thumb" data-ui-action="add-reference" ${dis}><span class="pr-placeholder">${uiPrintIcon('image')}<span>${p?'Thêm mẫu tham khảo':'Mẫu tham khảo'}</span></span></button><figcaption>${i===0&&!refs.length?'Pinterest / Google / Etsy':'Ảnh / link của bạn'}</figcaption></figure>`).join('');return `<section class="pr-section pr-refs ${p?'':'pr-disabled'}"><div class="pr-head"><h3>Ý tưởng & mẫu tham khảo</h3><span class="pr-spacer"></span>${uiPager('references',refs,4)}<button class="pr-link" data-ui-action="add-reference" ${dis}>${uiPrintIcon('plus')}Thêm ảnh / link</button></div><div class="pr-ref-grid">${cards}${fill}</div><small class="pr-hint">Tham khảo xu hướng để tạo thiết kế gốc; không sao chép mẫu.</small></section>`}
function uiPrintDesigns(p){const st=p?uiPrintStats(p):{assets:[],created:[],approved:[],count:Number(uiPrintNewDraft().count)||12},pg=uiPage(st.assets,uiState.pages.designs,3),dis=p?'':'disabled',batch=Math.min(30,Math.max(1,Number(uiState.printDrafts[p?.id]?.batchCount)||6)),offset=pg.page*3;const cards=pg.items.map((a,i)=>{const tone=!a.data?'muted':a.approval==='approved'?'green':'amber';return `<figure class="pr-design"><button class="pr-design-thumb" data-workflow="asset" data-wid="${a.id}" aria-label="Mở ${esc(a.title)}">${a.data?`<img src="${a.data}" alt="${esc(a.title)}">`:`<span class="pr-placeholder">${uiPrintIcon('image')}<span>Chưa có ảnh</span></span>`}</button><figcaption><span>Mẫu ${String(offset+i+1).padStart(2,'0')}</span><span class="pr-status ${tone}"><i></i>${!a.data?'Chưa có ảnh':a.approval==='approved'?'Đã duyệt':'Chờ duyệt'}</span></figcaption></figure>`}).join('');const fill=Array.from({length:Math.max(0,3-pg.items.length)},(_,i)=>`<figure class="pr-design empty"><button class="pr-design-thumb" data-ui-action="design-batch" ${dis}><span class="pr-placeholder">${uiPrintIcon('image')}<span>Chưa có thiết kế</span></span></button><figcaption><span>Mẫu ${String(offset+pg.items.length+i+1).padStart(2,'0')}</span><span class="pr-status muted"><i></i>Chưa tạo</span></figcaption></figure>`).join('');return `<section class="pr-section pr-designs ${p?'':'pr-disabled'}"><div class="pr-head"><h3>Thiết kế đang sản xuất</h3><span class="pr-spacer"></span><small>${st.created.length}/${st.count} thiết kế đã tạo · ${st.approved.length} thiết kế đã duyệt</small></div><div class="pr-design-grid">${cards}${fill}</div><div class="pr-batch"><button class="primary pr-primary" data-ui-action="design-batch" ${dis}>Tạo đợt thiết kế</button><label for="uDesignBatch">Số lượng:</label><input id="uDesignBatch" type="number" min="1" max="30" value="${batch}" ${dis}><small>Thiết kế mới luôn chờ bạn duyệt</small><span class="pr-spacer"></span>${uiPager('designs',st.assets,3)}<button class="pr-link" data-ui-action="upload-design" ${dis}>Nhập ảnh</button></div></section>`}
function uiPrintEtsy(p){const st=p?uiPrintStats(p):{approved:[]},w=p?db.workflows.find(w=>w.id===p.etsyWorkflowId):null,dis=p?'':'disabled',rows=[['image','Ảnh sản phẩm',st.approved.length?st.approved.length+' ảnh đã duyệt':'Chưa có ảnh duyệt',st.approved.length?'green':'muted'],['image','Tiêu đề & mô tả',w?.description?'Bản nháp':'Chưa tạo',w?.description?'blue':'amber'],['tag','13 thẻ tag',w?.tags?String(w.tags).split(',').filter(x=>x.trim()).length+' tag':'Chưa tạo',w?.tags?'green':'amber'],['price','Giá & loại sản phẩm',w?.price?'Đã thiết lập':'Chưa thiết lập',w?.price?'green':'red']];return `<section class="pr-section pr-etsy ${p?'':'pr-disabled'}"><h3>Chuẩn bị sản phẩm Etsy</h3><div class="pr-checklist">${rows.map(([ico,label,status,tone])=>`<button class="pr-check-row" data-ui-action="etsy-draft" ${dis}>${uiPrintIcon(ico)}<span>${label}</span><span class="pr-badge ${tone}">${esc(status)}</span>${uiPrintIcon('chevron')}</button>`).join('')}</div><button class="pr-outline pr-wide" data-ui-action="etsy-draft" ${dis}>Mở bản nháp sản phẩm</button><div class="pr-auto">${uiPrintIcon('clock')}<span>Tự động đăng / hẹn giờ: Chưa tích hợp</span><button class="pr-link" data-ui-printtab="publish">Xem kết nối đăng bán ${uiPrintIcon('arrow')}</button></div></section>`}
function uiPrintPanel(project){const p=project?{...project,...uiState.printDrafts[project.id]}:null,src=p||uiPrintNewDraft(),st=p?uiPrintStats(p):null,step=!p||!(p.keyword||(p.references||[]).length)?1:p.etsyWorkflowId?3:2;return `<section class="pr-panel"><div class="pr-title"><h2>${esc(p?p.title:'Bộ sản phẩm mới')}</h2><span class="pr-badge ${p?'green':'muted'}">${p?'Đang chuẩn bị':'Chưa triển khai'}</span><span class="pr-spacer"></span><span class="pr-badge gray">Tự động hóa: Chờ tích hợp</span></div>${uiPrintSteps(step)}${uiPrintSource(src,!p)}${uiPrintRefs(p)}<div class="pr-bottom">${uiPrintDesigns(p)}${uiPrintEtsy(p)}</div></section>`}
function uiPrint(){const list=db.printProjects||[];if(uiState.creatingPrint&&!list.length)uiState.creatingPrint=false;if(!uiState.creatingPrint&&!list.some(p=>p.id===uiState.print)){let saved='';try{saved=localStorage.getItem('xuong-print-selected')||''}catch{}uiState.print=list.some(p=>p.id===saved)?saved:list[0]?.id||''}const p=uiState.creatingPrint?null:list.find(p=>p.id===uiState.print);try{if(p)localStorage.setItem('xuong-print-selected',p.id)}catch{}return `<div class="pr-workspace">${uiPrintLibrary()}<div class="pr-studio"><div class="pr-heading"><div><h1>Xưởng In ấn</h1><p>Tìm ý tưởng, tạo thiết kế và chuẩn bị sản phẩm đăng Etsy.</p></div></div><div class="pr-tabs" role="tablist"><button role="tab" aria-selected="${uiState.printTab!=='publish'}" data-ui-printtab="produce" class="${uiState.printTab!=='publish'?'active':''}">Sản xuất thiết kế</button><button role="tab" aria-selected="${uiState.printTab==='publish'}" data-ui-printtab="publish" class="${uiState.printTab==='publish'?'active':''}">Kết nối đăng bán</button></div>${uiState.printTab==='publish'?uiPublishing('print',p):uiPrintPanel(p)}</div></div>`}
async function uiNewPrint(){uiFlushPrint();if(!uiState.creatingPrint)uiState.prevPrint=uiState.print;uiState.creatingPrint=true;uiState.print='';uiState.printTab='produce';view='prints';if(location.hash!=='#prints')location.hash='prints';uiRender();setTimeout(()=>$('#uPrintKeyword')?.focus(),0)}
async function uiCreatePrint(){const d=uiPrintNewDraft(),keyword=String(d.keyword||'').trim();if(!keyword){$('#uPrintKeyword')?.focus();throw Error('Nhập chủ đề / từ khóa trước.')}const count=Number(d.count)||12;if(!Number.isInteger(count)||count<1||count>100)throw Error('Số thiết kế từ 1 đến 100.');const p={id:uid(),title:uiWorkingTitle(keyword),keyword,productType:uiPrintProducts.includes(d.productType)?d.productType:'Áo thun',style:String(d.style||''),count,output:uiPrintOutputs.includes(d.output)?d.output:'PNG nền trong',sources:Array.isArray(d.sources)?d.sources.filter(x=>uiPrintSources.includes(x)):[...uiPrintSources],references:[]};uiPersist(()=>{db.printProjects??=[];db.printProjects.push(p)});uiState.print=p.id;uiState.creatingPrint=false;uiState.newPrint={};uiPrintKeepDraft();uiState.pages.prints=Math.floor((db.printProjects.length-1)/6);toast('Đã tạo bộ sản phẩm. Thêm mẫu tham khảo hoặc tạo đợt thiết kế.')}
async function uiFindReferences(p){const src=p?{...p,...uiState.printDrafts[p.id]}:uiPrintNewDraft(),q=String(src.keyword||'').trim(),sources=src.sources||uiPrintSources;if(!q){$('#uPrintKeyword')?.focus();throw Error('Nhập chủ đề / từ khóa để tìm tham khảo.')}if(!sources.length)throw Error('Chọn ít nhất một nguồn tham khảo.');const url={Pinterest:'https://www.pinterest.com/search/pins/?q=',Google:'https://www.google.com/search?tbm=isch&q=',Etsy:'https://www.etsy.com/search?q='};await uiReadDocument(`<p>Tự động lấy sản phẩm từ Pinterest / Google / Etsy chưa được tích hợp. Mở trang tìm kiếm bên dưới, chọn mẫu phù hợp rồi bấm <b>＋ Thêm ảnh / link</b> để lưu vào bộ sản phẩm.</p>${sources.map(n=>`<p>${safeLink(url[n]+encodeURIComponent(q),'Tìm “'+q+'” trên '+n)}</p>`).join('')}<p>Chỉ dùng để tham khảo xu hướng; thiết kế phải là bản gốc.</p>`,'Tìm sản phẩm tham khảo')}
function uiBridgeDetails(){const state=bridgeConnectionState(),present=!!bridgeStatus.ok,connected=present&&bridgeStatus.connected,last=(db.aiJobs||[]).filter(j=>j.resultText&&['ready','applied'].includes(j.status)).at(-1);return `<div class="u-card-head"><span class="u-kpi-icon">${uiIcon('plug')}</span><div><h2>ChatGPT Bridge</h2><p>Sản xuất nội dung và hình ảnh qua ChatGPT Plus.</p></div><span class="u-spacer"></span>${uiBadge(state.label.replace(' — không nhận được Bridge',''),state.tone==='connected'?'green':state.tone==='checking'?'amber':'red')}</div><div class="u-diagnostic">${[['Extension trên trình duyệt',present?'Đã nhận Bridge':'Chưa nhận được Bridge',present?'green':'red',present?'Bridge '+esc(bridgeStatus.version||'')+' phản hồi.':'Chưa phát hiện extension trong trang này.'],['Tab ChatGPT',connected?'Đã chọn tab':'Chưa xác nhận',connected?'green':'muted',connected?esc(bridgeStatus.conversation?.title||'ChatGPT'):'Chưa xác nhận đã chọn tab ChatGPT.'],['Gửi / nhận kết quả',last?'Đã nhận kết quả':'Chưa kiểm tra',last?'green':'muted',last?'Có kết quả được lưu trong Xưởng.':'Chưa kiểm tra khả năng gửi / nhận kết quả.']].map(([label,status,tone,help])=>`<div><strong>${label}</strong>${uiBadge(status,tone)}<small>${help}</small></div>`).join('')}</div><small>Phiên bản hỗ trợ: 0.4.0 &nbsp; | &nbsp; Không dùng API key</small>`}
function uiSettings(){return `<div class="u-settings">${uiHeader('Cài đặt','Kết nối công cụ và quản lý dữ liệu cho toàn bộ Xưởng.')}<p class="u-settings-note">Dùng chung cho Xưởng Truyện và Xưởng In ấn.</p><div class="u-settings-grid"><div class="u-settings-left"><section class="u-card u-bridge-card"><div id="uBridgeSettings">${uiBridgeDetails()}</div><div class="u-actions"><button class="primary" data-ui-action="bridge-check">Kiểm tra kết nối</button><a class="u-button" href="/downloads/" target="_blank" rel="noopener">Tải Bridge 0.4.0</a><button class="u-text" data-ui-action="bridge-help">Hướng dẫn cài / cập nhật</button></div><div class="u-setup"><strong>Kết nối lần đầu</strong><ol><li>Cài Bridge trong Chrome hoặc Edge</li><li>Chọn tab ChatGPT trong popup extension</li><li>Tải lại Xưởng và kiểm tra kết nối</li></ol><p class="u-blue">ⓘ Nếu mở Xưởng trong khung ChatGPT, hãy thử mở bằng tab trình duyệt riêng.</p></div><div class="u-setup u-package-note"><p><b>Gói ZIP:</b> 1 thư mục Xuong_ChatGPT_Bridge</p><p><b>Cập nhật:</b> ghi đè file trong thư mục đã cài → Tải lại extension.</p></div></section><section class="u-card u-common"><h2>${uiIcon('settings')} Cách vận hành chung</h2><div class="u-common-fields"><label>Ngôn ngữ giao diện<select aria-label="Ngôn ngữ giao diện"><option>Tiếng Việt</option></select></label><label>Giao diện<span class="u-segment"><button data-ui-theme="light" class="${!document.documentElement.classList.contains('dark')?'selected':''}">Sáng</button><button data-ui-theme="dark" class="${document.documentElement.classList.contains('dark')?'selected':''}">Tối</button></span></label><div><span>Lưu thay đổi</span><p class="u-dot ${loadError?'red':'green'}">${loadError?'Cần khôi phục':'Tự động trên trình duyệt'}</p></div></div><div class="u-rule green"><b>♙ Duyệt trước khi đăng</b><span>Luôn bật</span><small>Truyện, hình ảnh và sản phẩm đều cần bạn duyệt.</small></div><div class="u-rule"><b>◷ Khi kết nối bị gián đoạn</b><span>Giữ công việc để tiếp tục</span><small>Không tự tạo lại nội dung đã có kết quả.</small></div></section></div><div class="u-settings-right"><section class="u-card"><h2>${uiIcon('settings')} Phần mềm tự động hóa</h2><div class="u-integration"><div><strong>Claude Code / Bộ tự động hóa</strong><small>Tìm ý tưởng sản phẩm, chuẩn bị và đăng Etsy.</small></div>${uiBadge('Chưa tích hợp')}</div><div class="u-integration"><div><strong>Phần mềm khác</strong><small>Kết nối thêm công cụ khi được hỗ trợ.</small></div>${uiBadge('Chưa cấu hình')}</div><button data-ui-action="software">Xem cấu hình kết nối</button>${uiHint('Chỉ hiển thị Đã kết nối sau khi công cụ phản hồi.')}</section><section class="u-card"><h2>${uiIcon('coins')} Lưu trữ & sao lưu</h2><div class="u-settings-row"><strong>Nơi lưu dữ liệu</strong><span>Trình duyệt hiện tại</span></div><div class="u-settings-row"><strong>Yêu cầu xuất gần nhất</strong>${uiBadge(db.uiSettings?.lastBackupAt?dateText(db.uiSettings.lastBackupAt):'Chưa có bản sao lưu',db.uiSettings?.lastBackupAt?'green':'amber')}</div><p>Chưa có đồng bộ giữa các thiết bị.</p><div class="u-actions"><button data-ui-action="backup">Xuất bản sao lưu</button><button data-ui-action="restore">Khôi phục dữ liệu</button><button class="u-text" data-ui-action="csv">Xuất CSV</button></div><small>Sao lưu trước khi đổi trình duyệt hoặc thiết bị.</small></section><section class="u-card"><h2>${uiIcon('info')} Thông tin & cập nhật</h2><div class="u-settings-row"><span>Phiên bản web</span><span>0.5.0</span></div><div class="u-settings-row"><span>Gói Bridge hiện tại</span><span>0.4.0</span></div><div class="u-actions u-right"><button class="u-text" data-ui-action="updates">Xem lịch sử cập nhật</button><button class="u-text" data-ui-action="bug">Báo lỗi</button><button class="u-text" data-ui-action="tools">Công cụ khác</button></div></section></div></div>${uiHint('Tài khoản đăng truyện và cửa hàng Etsy được quản lý tại Kết nối đăng truyện / Kết nối đăng bán trong từng Xưởng.')}</div>`}
function uiPublishing(type,project){const channels=db.channels.filter(c=>type==='print'?c.platform==='Etsy':['Webnovel','Web truyện','Webtoon'].includes(c.platform)),chapters=project&&type==='story'?lfChapters(project):[],p=uiPage(chapters,uiState.pages.publish,5);return `<section class="u-card u-publishing"><div class="u-card-head"><h2>${type==='story'?'Kênh đăng truyện':'Cửa hàng Etsy'}</h2>${uiPager(type+'Channels',channels,2)}<button data-new="channels">＋ Thêm kênh</button></div>${uiHint('Đăng tự động qua API chưa được tích hợp. Lịch bên dưới là lịch nội bộ; bạn xác nhận sau khi đăng trên nền tảng.')}<div class="u-channel-grid">${uiPage(channels,uiState.pages[type+'Channels'],2).items.map(c=>`<article class="u-section"><strong>${esc(c.name)}</strong>${uiBadge('Đăng thủ công','amber')}<p>${esc(c.platform)}</p><div class="u-actions"><button data-edit="channels" data-id="${c.id}">Chỉnh sửa kênh</button>${safeLink(c.adminUrl||c.link,'Mở nền tảng')}</div></article>`).join('')||'<p class="u-empty">Chưa có kênh. Thêm kênh để chuẩn bị lịch đăng.</p>'}</div><div class="u-card-head"><h3>${project?esc(project.title):'Lịch nội dung'}</h3>${type==='story'&&project?'<button data-ui-action="schedule">Xếp lịch chương đã duyệt</button>':''}${uiPager('publish',chapters,5)}</div><table class="u-table"><thead><tr><th>Nội dung</th><th>Trạng thái</th><th>Thời gian dự kiến</th><th>Thao tác</th></tr></thead><tbody>${p.items.map(c=>`<tr><td>${esc(c.title)}</td><td>${esc(statuses[c.status])}</td><td>${dateText(c.scheduledAt)}</td><td><button data-edit="content" data-id="${c.id}">Mở chương</button></td></tr>`).join('')||`<tr><td colspan="4" class="u-empty">${type==='print'?'Mở bản nháp sản phẩm trong Sản xuất thiết kế để chuẩn bị nội dung.':'Chương và lịch đăng của bộ truyện sẽ xuất hiện tại đây.'}</td></tr>`}</tbody></table></section>`}
function uiRender(){const route=uiRoute(view);if(!uiLabels[route]){uiLegacyRender();uiChrome('');document.body.classList.add('u-legacy');return}document.body.classList.remove('u-legacy');document.body.classList.add('u-app');view=route;uiChrome(route);$('#main').innerHTML=({overview:uiOverview,series:uiStory,prints:uiPrint,settings:uiSettings})[route]();uiCompactPanels(route);$('#main').dataset.screen=route;$('#breadcrumb').textContent='Xưởng Nội Dung / '+uiLabels[route]}
async function uiTools(){const d=await choose('Công cụ hiện có',select('tool','Chọn công cụ',[['channels','Kênh'],['prompts','Thư viện câu lệnh'],['content','Nội dung'],['metrics','Số liệu'],['asset','Hình ảnh']], 'channels'));if(!d)return;if(d.tool==='asset'){openWorkflow('asset');return}const type=d.tool;await uiReadDocument(`<div class="u-spread"><h3>Dữ liệu hiện có</h3><button data-new="${type}">＋ Thêm mới</button></div>`+(db[type]||[]).map(row=>`<article class="u-chapter-row"><strong>${esc(row.title||row.name||row.date||row.id)}</strong><button data-edit="${type}" data-id="${row.id}">Mở / sửa</button>${type==='prompts'?`<button data-preview="${row.id}">Dùng câu lệnh</button>`:''}</article>`).join(''),'Công cụ hiện có')}
function uiCompactPanels(route){if(innerHeight>850)return;if(route==='settings'){const grid=document.querySelector('.u-settings-grid'),left=grid.children[0],right=grid.children[1];uiState.compact??={};const selected=uiState.compact.settings||0,nav=document.createElement('div');nav.className='u-segment u-settings-pages';nav.innerHTML=['Kết nối công cụ','Dữ liệu & vận hành'].map((label,i)=>`<button class="${i===selected?'selected':''}" data-ui-panel="settings" data-panel-index="${i}">${label}</button>`).join('');grid.before(nav);left.children[0].hidden=selected!==0;left.children[1].hidden=selected!==1;right.children[0].hidden=selected!==0;right.children[1].hidden=selected!==1;right.children[2].hidden=selected!==1;grid.classList.add('u-compact-settings');return}if(route!=='prints')return;const panel=document.querySelector(route==='series'?'.u-book-panel':'.u-print-panel');if(!panel)return;const items=route==='series'?[...panel.querySelectorAll(':scope>.u-section')]:[...panel.children].filter(el=>el.matches('.u-section,.u-print-bottom')),labels=route==='series'?['Ý tưởng & nguồn','Cốt truyện & nhân vật','Đợt chương']:['Nguồn & phong cách','Mẫu tham khảo','Thiết kế & Etsy'];uiState.compact??={};const selected=Math.min(uiState.compact[route]||0,items.length-1),nav=document.createElement('div');nav.className='u-panel-pages u-segment';nav.innerHTML=items.map((el,i)=>`<button class="${i===selected?'selected':''}" data-ui-panel="${route}" data-panel-index="${i}">${labels[i]}</button>`).join('');panel.children[1].after(nav);panel.classList.add('u-compact-panel');items.forEach((el,i)=>{el.hidden=i!==selected;el.classList.add('u-panel-page')})}
function uiPersist(fn){const before=JSON.stringify(db);try{fn();if(!save())throw Error('Không lưu được thay đổi.')}catch(e){db=JSON.parse(before);throw e}}
function uiSelectedBook(){return db.series.find(s=>s.id===uiState.book)}
function uiSelectedPrint(){return db.printProjects.find(p=>p.id===uiState.print)}
function uiFlushBook(){const s=uiSelectedBook(),draft=uiState.drafts[s?.id];if(!s||!draft)return;const current=lfPipeline(s).source,next={...current,...draft};if(JSON.stringify(current)!==JSON.stringify(next))uiPersist(()=>lfSetSource(s,next));delete uiState.drafts[s.id]}
function uiFlushPrint(){const p=uiSelectedPrint(),draft=uiState.printDrafts[p?.id];if(p&&draft)uiPersist(()=>Object.assign(p,draft));delete uiState.printDrafts[p?.id]}
async function uiNewBook(){uiFlushBook();if(!uiState.creating)uiState.prevBook=uiState.book;uiState.creating=true;uiState.book='';uiState.storyTab='produce';view='series';if(location.hash!=='#series')location.hash='series';uiRender();setTimeout(()=>$('#uStoryIdea')?.focus(),0)}
async function uiBuildStory(s){uiFlushBook();const [stage,,kind]=uiCurrentStage(s);if(stage==='ready'){if(!await uiConfirm('Tạo lại concept sẽ cần duyệt lại các phần phụ thuộc. Chương đã duyệt vẫn được giữ. Tiếp tục?'))return;return await lfSend(s,'GENERATE_CONCEPT')}const artifact=lfPipeline(s).artifacts[stage];if(artifact&&artifact.dependency===lfDependency(s,stage))return uiReviewStage(s,stage);if(stage==='dna'){const next=lfNextDNA(s);if(next.complete){lfArtifact(s,'dna',next.value);save();return}await lfSend(s,kind,next.scope)}else await lfSend(s,kind)}
async function uiReviewStage(s,stage){const a=lfPipeline(s).artifacts[stage];if(!a)throw Error('Chưa có kết quả để duyệt.');const labels={reviewVi:'Bản tiếng Việt để duyệt',title:'Tên truyện',logline:'Logline',premise:'Cốt truyện tổng quan',mainThreads:'Twist & nút thắt',originalityNotes:'Điểm khác biệt',world:'Thế giới',worldRules:'Quy tắc thế giới'};const text=Object.entries(a.value).sort(([x],[y])=>(y==='reviewVi')-(x==='reviewVi')).map(([k,v])=>`<p><b>${esc(labels[k]||k)}</b></p><p>${esc(typeof v==='string'?v:JSON.stringify(v,null,2))}</p>`).join('');await uiReadDocument(text,stage==='bible'?'Cốt truyện tổng quan':stage==='characters'?'Nhân vật':'Kết quả để duyệt')}
async function uiReadDocument(html,title='Nội dung'){const pending=choose(title,`<div class="u-reader">${html}</div>`);const reader=$('#pickerFields .u-reader');let split=false;for(const child of [...reader.children])if(['PRE','P'].includes(child.tagName)&&child.textContent.length>800){const nodes=uiSplitText(child.textContent).map(part=>{const node=document.createElement(child.tagName);node.textContent=part;return node});child.replaceWith(...nodes);split=true}uiPaginateContainer(reader,split||reader.querySelector('pre')?1:4);await pending}
async function uiEditBible(s){const a=lfPipeline(s).artifacts.bible;if(!a){toast('Xây dựng cốt truyện trước để chỉnh sửa.');return}const d=await choose('Điều chỉnh cốt truyện',input('title','Tên truyện',a.value.title)+input('premise','Cốt truyện tổng quan',a.value.premise,'textarea')+input('mainThreads','Twist & nút thắt',a.value.mainThreads,'textarea'));if(!d)return;const value={...a.value,...d};if(['title','premise','mainThreads'].some(k=>d[k]!==a.value[k]))delete value.reviewVi;lfValidateOutput(s,'GENERATE_STORY_BIBLE',value);uiPersist(()=>lfArtifact(s,'bible',value))}
async function uiReference(s){const p=lfPipeline(s),d=await choose('Script / transcript tham khảo',input('script','Dán nội dung nguồn (link chỉ dùng để lưu tham khảo)',p.source.script||'','textarea','rows="12"'));if(!d)return;uiFlushBook();uiPersist(()=>lfSetSource(s,{...p.source,mode:d.script.trim()?'reference':'topic',script:d.script}));toast('Đã lưu nguồn. Script dài được chia theo mạch nội dung.')}
async function uiBatch(s){uiFlushBook();if(!lfApproved(s,'outline'))throw Error('Duyệt cốt truyện, nhân vật và dàn ý trước khi viết chương.');const count=Number($('#uChapterCount').value);if(!Number.isInteger(count)||count<1||count>30)throw Error('Mỗi đợt từ 1 đến 30 chương.');const next=lfNextChapter(s);uiPersist(()=>s.uiBatch={id:uid(),start:next,end:next+count-1,count,ending:$('#uEnding').value,options:$('#uBatchOptions').value,status:'preparing'});if(!lfPlans(s,next).some(p=>p.kind==='chapter')){await lfSend(s,'GENERATE_OUTLINE',{extendTo:next+count-1,preserveExisting:true});toast('Đã yêu cầu mở rộng dàn ý. Bạn duyệt kế hoạch mới trước khi viết.');return}const defaults=lfChapterDefaults(s),ending={continue:'Tiếp tục phát triển câu chuyện.',arc:'Phát triển sâu Arc hiện tại; chưa khép các nút thắt chính của Arc.',newarc:'Khép dần Arc hiện tại và mở một Arc mới có xung đột mới.',open:'Chuẩn bị kết mở, giải quyết xung đột trung tâm nhưng giữ khả năng tiếp nối.',closed:'Chuẩn bị kết đóng trọn vẹn, giải quyết các nút thắt bằng sự kiện thực sự.'}[s.uiBatch.ending]||'';defaults.prompt+='\n'+ending+'\n'+s.uiBatch.options;openEditor('content','',defaults);toast('Đã chuẩn bị đợt chương. Viết và duyệt từng chương để giữ đúng ngữ cảnh.')}
async function uiAddReference(p){uiFlushPrint();const d=await choose('Thêm mẫu tham khảo',input('title','Tên mẫu','','text','required')+input('link','Link tham khảo','','url')+'<p>Để thêm ảnh từ máy, chọn Nhập ảnh tham khảo ở bước sau.</p>'+select('mode','Cách thêm',[['link','Lưu link'],['image','Nhập ảnh tham khảo']],'link'));if(!d)return;if(d.mode==='image')return uiImportImage(p,'reference',d.title,d.link);if(!d.link)throw Error('Nhập link tham khảo.');if(!/^https?:\/\//i.test(d.link))throw Error('Link phải là http hoặc https.');uiPersist(()=>p.references.push({id:uid(),title:d.title,link:d.link,source:new URL(d.link).hostname}));}
function uiImportImage(p,type,title='',link=''){const file=document.createElement('input');file.type='file';file.accept='image/png,image/jpeg,image/webp';file.onchange=async()=>{const f=file.files[0];if(!f)return;try{if(f.size>5*1024*1024||!['image/png','image/jpeg','image/webp'].includes(f.type))throw Error('Chọn ảnh PNG, JPEG hoặc WebP tối đa 5 MB.');const data=await new Promise((resolve,reject)=>{const r=new FileReader;r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Không đọc được ảnh.'));r.readAsDataURL(f)});uiPersist(()=>{if(type==='reference')p.references.push({id:uid(),title:title||f.name,link,data,source:'Ảnh của bạn'});else db.assets.push({id:uid(),printProjectId:p.id,title:title||f.name,approval:'draft',data,ratio:'1:1',prompt:p.style||'',createdAt:new Date().toISOString()})});uiRender()}catch(e){toast(e.message)}};file.click()}
async function uiNewDesign(p,preset){uiFlushPrint();const d=preset?{count:preset.count,prompt:p.style||''}:await choose('Tạo đợt thiết kế',input('count','Số thiết kế (tạo từng ảnh qua Bridge)',1,'number','min="1" max="30"')+input('prompt','Yêu cầu cho đợt này',p.style||'','textarea'));if(!d)return;const count=Number(d.count);if(!Number.isInteger(count)||count<1||count>30)throw Error('Số thiết kế từ 1 đến 30.');const assets=Array.from({length:count},(_,i)=>({id:uid(),title:p.title+' — Mẫu '+(db.assets.filter(a=>a.printProjectId===p.id).length+i+1),printProjectId:p.id,approval:'draft',ratio:'1:1',prompt:[p.keyword,d.prompt,(p.references||[]).some(r=>r.selected)?'Trend references (inspiration only, do not copy): '+p.references.filter(r=>r.selected).map(r=>r.title+(r.link?' '+r.link:'')).join('; '):'','Create an original printable design. '+p.output].filter(Boolean).join('\n'),globalStyle:d.prompt,scenePrompt:p.keyword,createdAt:new Date().toISOString()}));uiPersist(()=>db.assets.push(...assets));uiRender();openWorkflow('asset',assets[0].id);}
async function uiEtsyDraft(p){uiFlushPrint();let c=db.channels.find(c=>c.platform==='Etsy');if(!c){if(!await uiConfirm('Chưa có kênh Etsy. Tạo kênh Etsy để lưu bản nháp sản phẩm?'))return;uiPersist(()=>{c={id:uid(),name:'Etsy',platform:'Etsy',link:'https://www.etsy.com/',style:'',visual:''};db.channels.push(c)})}let w=db.workflows.find(w=>w.id===p.etsyWorkflowId);if(!w){const a=db.assets.find(a=>a.printProjectId===p.id&&a.approval==='approved');w={id:uid(),title:p.title,channelId:c.id,type:'etsy',status:'draft',description:'',tags:'',currency:'USD',price:'',imageId:a?.id||'',createdAt:new Date().toISOString()};uiPersist(()=>{db.workflows.push(w);p.etsyWorkflowId=w.id})}openWorkflow('etsy',w.id)}
async function uiRestore(){const d=await choose('Khôi phục dữ liệu',input('json','Dán JSON bản sao lưu','','textarea','rows="12"')+'<p>Khôi phục thay thế dữ liệu hiện tại. Hãy xuất bản sao lưu trước.</p>');if(!d)return;const next=JSON.parse(d.json);validate(next);uiValidatePrintRecords(next);if(!await uiConfirm('Thay thế dữ liệu hiện tại bằng bản sao lưu này?'))return;const before=db,beforeError=loadError;db=next;loadError=false;db.assets??=[];db.workflows??=[];db.aiJobs??=[];db.printProjects??=[];if(!save()){db=before;loadError=beforeError;return}uiState.book='';uiState.print='';uiState.drafts={};uiState.printDrafts={};uiState.batchDrafts={};uiState.pages={};toast('Đã khôi phục dữ liệu.')}
async function uiActivity(){const rows=db.content.filter(c=>c.status==='review'),jobs=(db.aiJobs||[]).filter(j=>['ready','error','waiting_send','running'].includes(j.status));await uiReadDocument(`<h3>Nội dung chờ duyệt (${rows.length})</h3>${rows.map(c=>`<p>${esc(c.title)} <button data-edit="content" data-id="${c.id}">Mở</button></p>`).join('')||'<p>Không có nội dung chờ duyệt.</p>'}<h3>Công việc AI (${jobs.length})</h3>${jobs.map(j=>`<p>${esc(j.title)} — ${esc(jobState(j))} ${j.resultText?`<button data-ui-result="${j.id}">Xem kết quả</button>`:''}</p>`).join('')}`,'Công việc cần xử lý')}
async function uiReport(){const t=uiTotals(uiState.month);await uiReadDocument(`<div class="u-spread"><h3>Báo cáo ${esc(uiState.month)}</h3><button data-new="metrics">＋ Ghi số liệu</button></div><p>Doanh thu: ${money(t.revenue)} · Chi phí: ${money(t.cost)} · Lợi nhuận: ${money(t.profit)}</p>${t.rows.map(m=>`<p>${esc(m.date)} — ${esc(channelName(m.channelId))} — ${money(m.revenue)} <button data-edit="metrics" data-id="${m.id}">Sửa</button></p>`).join('')||'<p>Chưa có số liệu. Bấm Ghi số liệu để nhập.</p>'}`,'Báo cáo doanh thu')}
async function uiChapterList(s){await uiReadDocument(`<div class="u-spread"><h3>${esc(s.title)}</h3><button data-ui-action="batch">＋ Chương tiếp theo</button></div>${lfChapters(s).map(c=>`<article class="u-chapter-row"><div><strong>Chương ${Number(c.chapterNumber)||'?'} — ${esc(c.title)}</strong><small>${esc(statuses[c.status])}${c.parentId?' · Revision':''} · ${esc(lfCheckSummary(lfChapterCheck(s,c.body)).label)}${lfAIReviewFresh(c)?' · ChatGPT: '+(c.aiReview.value.verdict==='ok'?'Đạt':'Cần sửa'):''}</small></div><button data-edit="content" data-id="${c.id}">Mở</button>${lfReviewFresh(c)?`<button data-ui-review-vi="${c.id}">Bản tiếng Việt</button>`:lfNeedsReview(s)&&c.body?`<button data-ui-translate="${c.id}">${c.reviewVi?'Dịch lại để duyệt':'Dịch để duyệt'}</button>`:''}${['approved','live'].includes(c.status)?`<button data-ui-revision="${c.id}">Tạo Revision</button><button data-ui-memory="${c.id}">Cập nhật memory</button>${lfData(s).memoryDrafts?.[c.id]?.status==='review'?`<button data-ui-approve-memory="${c.id}">Duyệt memory</button>`:''}`:''}</article>`).join('')||'<p>Chưa có chương.</p>'}`,'Danh sách chương')}
async function uiSchedule(s){const list=lfChapters(s).filter(c=>c.status==='approved');if(!list.length)throw Error('Chưa có chương đã duyệt để xếp lịch.');const d=await choose('Lịch đăng nội bộ',select('chapterId','Chương đã duyệt',list.map(c=>[c.id,c.title]),list[0].id)+input('scheduledAt','Thời gian dự kiến','','datetime-local','required'));if(!d)return;const c=list.find(c=>c.id===d.chapterId);uiPersist(()=>{c.scheduledAt=d.scheduledAt;c.updatedAt=new Date().toISOString()});toast('Đã lưu lịch nội bộ; không tự đăng lên nền tảng.')}
function uiPaginateContainer(container,size=4){if(!container)return;if(container.nextElementSibling?.classList.contains('u-dialog-pages'))container.nextElementSibling.remove();const children=[...container.children].filter(el=>el.tagName!=='INPUT'||el.type!=='hidden');if(children.length<=size)return;let index=0;const max=Math.ceil(children.length/size),pager=document.createElement('div');pager.className='u-dialog-pages';pager.innerHTML='<button type="button">‹ Trước</button><span></span><button type="button">Sau ›</button>';container.after(pager);const update=()=>{children.forEach((el,i)=>el.hidden=Math.floor(i/size)!==index);pager.children[0].disabled=index===0;pager.children[2].disabled=index===max-1;pager.children[1].textContent=(index+1)+' / '+max};container.addEventListener('invalid',e=>{const child=children.find(el=>el===e.target||el.contains(e.target));if(child){index=Math.floor(children.indexOf(child)/size);update()}},true);pager.children[0].onclick=()=>{index--;update()};pager.children[2].onclick=()=>{index++;update()};update()}
function uiPaginatePicker(){const c=$('#pickerFields .u-reader');if(c)uiPaginateContainer(c,4)}
function uiPaginateWorkflow(){uiPaginateContainer($('#workflowFields'),5)}
const uiBaseChoose=choose;choose=function(title,html){const pending=uiBaseChoose(title,html);uiPaginateContainer($('#pickerFields'),3);return pending};
